# Generated by plotwork generate from the source services (compose: compose.yaml). # The next run writes over this file. Put changes in docs/architecture.services.overrides.json, or run plotwork generate --capture # after an edit to keep it there, then run plotwork generate. # Fingerprint: 0a83be2403e4fdba flow "Parcelpoint services on a laptop" direction=down desc="The 5 services of a Docker Compose file in 2 networks, with 1 named volume. Each arrow points from a service to one it depends on."
node tracking_data_volume storage "tracking-data" sub="Named volume"
group edge_net "edge" type=network { node web service "web" sub="build ./web, port 3000" node api service "api" sub="ghcr.io/parcelpoint/tracking-api:1.8.2, port 8080" }
group data_net "data" type=network { node worker service "worker" sub="ghcr.io/parcelpoint/event-worker:1.8.2" icon=lucide:server node db_1 database "db" sub="postgres:16-alpine" icon=simple:postgresql node queue queue "queue" sub="rabbitmq:3.13-management" icon=simple:rabbitmq }
web -> api api -> db_1 api -> queue worker -> db_1 worker -> queue db_1 -> tracking_data_volume : "mounts" icon=lucide:hard-drive role=data
